export function assetReviewStatus(a){return a.reviewStatus||(a.active===false?'alternate':'accepted')}
export function searchAssets(assets,query='',status='all'){const terms=String(query).toLowerCase().split(/\s+/).filter(Boolean);return assets.filter(a=>{const review=assetReviewStatus(a),active=a.active!==false;return (status==='all'||status==='active'&&active||status==='inactive'&&!active||status===review)&&terms.every(q=>[a.id,a.label,a.src,a.kind,a.method,a.description,review,...(a.tags||[])].join(' ').toLowerCase().includes(q))})}
export function fingerprintRGBA(data,width,height){const sample=(x,y)=>{const i=(Math.min(height-1,Math.floor(y))*width+Math.min(width-1,Math.floor(x)))*4,a=data[i+3]/255;return (.299*data[i]+.587*data[i+1]+.114*data[i+2])*a+255*(1-a)},bits=[],hist=Array(8).fill(0);for(let y=0;y<8;y++)for(let x=0;x<8;x++){const l=sample((x+.5)*width/9,(y+.5)*height/8),r=sample((x+1.5)*width/9,(y+.5)*height/8);bits.push(+(l>r))}for(let y=0;y<height;y++)for(let x=0;x<width;x++)hist[Math.min(7,Math.floor(sample(x,y)/32))]++;const count=width*height;return {hash:Array.from({length:16},(_,i)=>parseInt(bits.slice(i*4,i*4+4).join(''),2).toString(16)).join(''),histogram:hist.map(v=>v/count)}}
export function fingerprintDistance(a,b){if(!a||!b)return 1;let different=0;for(let i=0;i<16;i++){let n=parseInt(a.hash[i],16)^parseInt(b.hash[i],16);while(n){different+=n&1;n>>=1}}const histogram=a.histogram.reduce((s,v,i)=>s+Math.abs(v-b.histogram[i]),0)/2;return different/64*.8+histogram*.2}
export function rankByPicture(assets,reference,sha256=''){return assets.filter(a=>['image','video'].includes(a.kind)&&a.fingerprint).map(a=>({asset:a,distance:sha256&&a.sha256===sha256?0:fingerprintDistance(reference,a.fingerprint),exact:!!sha256&&a.sha256===sha256})).sort((a,b)=>a.distance-b.distance||a.asset.label.localeCompare(b.asset.label))}
